package com.spdb.message;

import com.spdb.message.utils.AuthUtil;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.stereotype.Service;
import java.util.*;
import java.util.concurrent.*;

@Service
public class AnaMessageSendService {
 private final NamedParameterJdbcTemplate jdbc; private final ResponseMessageParser parser=new ResponseMessageParser(); private final HttpRequestMessageSender sender=new HttpRequestMessageSender();
 private volatile boolean running;
 public AnaMessageSendService(NamedParameterJdbcTemplate jdbc){this.jdbc=jdbc;}
 public synchronized void start(String target,int concurrency,int batch,int retries,int timeout){if(running)return; running=true; ExecutorService pool=Executors.newFixedThreadPool(Math.max(1,concurrency)); CompletableFuture.runAsync(()->{try{while(running){List<Map<String,Object>> rows=claim(target,batch); if(rows.isEmpty())break; for(Map<String,Object> row:rows) pool.submit(()->sendOne(row,target,retries,timeout));}}finally{pool.shutdown();running=false;} });}
 public void stop(){running=false;}
 public boolean isRunning(){return running;}
 public Map<String,Object> stats(){return jdbc.queryForMap("select count(*) filter(where send_status='PENDING') pending, count(*) filter(where send_status='SENDING') sending, count(*) filter(where send_status='SUCCESS') success, count(*) filter(where send_status='FAILED') failed from ana_msg_flow_log_request",new MapSqlParameterSource());}
 private List<Map<String,Object>> claim(String target,int batch){return jdbc.query("select source_ip,trans_id,txn_code,message_type,request_message,send_attempts from ana_msg_flow_log_request where send_status in ('PENDING','FAILED') order by txn_time nulls last limit :n",new MapSqlParameterSource("n",Math.max(1,batch)),(rs,n)->{Map<String,Object> m=new HashMap<>();m.put("source_ip",rs.getString(1));m.put("trans_id",rs.getString(2));m.put("txn_code",rs.getString(3));m.put("message_type",rs.getString(4));m.put("request_message",rs.getBytes(5));m.put("send_attempts",rs.getInt(6)); int claimed=jdbc.update("update ana_msg_flow_log_request set send_status='SENDING',send_attempts=send_attempts+1 where source_ip=:ip and trans_id=:id and send_status in ('PENDING','FAILED')",new MapSqlParameterSource().addValue("ip",m.get("source_ip")).addValue("id",m.get("trans_id")));return claimed==1?m:null;}).stream().filter(Objects::nonNull).toList();}
 private void sendOne(Map<String,Object> r,String target,int retries,int timeout){String ip=(String)r.get("source_ip"),id=(String)r.get("trans_id"),type=(String)r.get("message_type");try{String mic=val("micServId","10530013");String protocol=target.toLowerCase()+"_"+(type==null?"":type.toLowerCase());List<String> addresses=jdbc.query("select service_address from tss_service_control where protocol_id=:p",new MapSqlParameterSource("p",protocol),(rs,n)->rs.getString(1));if(addresses.isEmpty())throw new IllegalStateException("未找到服务地址:"+protocol);List<String> all=new ArrayList<>();for(String a:addresses)for(String x:a.split(","))if(!x.isBlank())all.add(x.trim());if(all.isEmpty())throw new IllegalStateException("服务地址为空");String address=all.get(ThreadLocalRandom.current().nextInt(all.size()));String authType=switch(type==null?"":type.trim().toLowerCase()){case "bzjson"->"json";case "soap"->"xml";case "sop"->"sop";case "sop2cbsp"->"spec";default->type==null?"":type.toLowerCase();};String authProtocol=target.toLowerCase()+"_"+authType;List<Map<String,Object>> auths=jdbc.query("select sid,gk,wk,pk from tss_service_auth where protocol_id=:p",new MapSqlParameterSource("p",authProtocol),(rs,n)->{Map<String,Object> m=new HashMap<>();m.put("sid",rs.getString(1));m.put("gk",rs.getString(2));m.put("wk",rs.getString(3));m.put("pk",rs.getString(4));return m;});if(auths.isEmpty())throw new IllegalStateException("未找到服务密钥:"+authProtocol);Map<String,Object> au=auths.get(0);if(au.get("gk")==null||au.get("pk")==null||au.get("wk")==null)throw new IllegalStateException("服务密钥不完整:"+authProtocol);String auth=AuthUtil.packToken((String)au.get("sid"),(String)au.get("gk"),(String)au.get("pk"),(String)au.get("wk"));var response=sender.send(address,type,(byte[])r.get("request_message"),mic,auth,timeout);String code=parser.parseReturnCode(type,response.body());jdbc.update("insert into ana_msg_flow_log_response(source_ip,trans_id,response_time,txn_code,message_type,response_message,return_code,http_status,service_address) values(:ip,:id,:t,:txn,:type,:body,:code,:status,:addr)",new MapSqlParameterSource().addValue("ip",ip).addValue("id",id).addValue("t",System.currentTimeMillis()).addValue("txn",r.get("txn_code")).addValue("type",type).addValue("body",response.body()).addValue("code",code).addValue("status",response.statusCode()).addValue("addr",address));jdbc.update("update ana_msg_flow_log_request set send_status=:s,send_time=current_timestamp,send_http_status=:h,send_error=null where source_ip=:ip and trans_id=:id",new MapSqlParameterSource().addValue("s",response.statusCode()/100==2?"SUCCESS":"FAILED").addValue("h",response.statusCode()).addValue("ip",ip).addValue("id",id));}catch(Exception e){String msg=String.valueOf(e.getMessage());jdbc.update("update ana_msg_flow_log_request set send_status='FAILED',send_time=current_timestamp,send_error=:e where source_ip=:ip and trans_id=:id",new MapSqlParameterSource().addValue("e",msg.substring(0,Math.min(1000,msg.length()))).addValue("ip",ip).addValue("id",id));}}
 private String val(String k,String d){List<String> v=jdbc.query("select config_value from system_config where config_key=:k",new MapSqlParameterSource("k",k),(rs,n)->rs.getString(1));return v.isEmpty()?d:v.get(0);}
}
